-- 57266819-9145-405f-8c62-2bd5a125c6b4
update public.products set
  name_de = $n$Ecksofa VEGAS U-Form – große Wohnlandschaft, moderner Stil$n$,
  color_de = $c$Grau$c$,
  material_de = $m$Monolith$m$,
  description_sections_de = $secs$[{"kind":"image","caption":"Premium-Ecksofa – Eleganz, Komfort und modernes Design","image_alt":"MODERNES ECKSOFA VEGAS U MIT VERSTELLBAREN KOPFSTÜTZEN","image_url":"https://tlvgsddpiikolgdwuwmc.supabase.co/storage/v1/object/public/products/1782133280908-4e5b9339-c315-492b-a78b-c6a5016f45e8.jpg"},{"body":"Premium-Ecksofa – Eleganz, Komfort und modernes Design\n\nSchaffen Sie sich einen Raum, in den Sie immer wieder mit Freude zurückkehren. Dieses außergewöhnliche Ecksofa in U-Form vereint modernes Design, höchsten Komfort und eine Funktionalität, die selbst die anspruchsvollsten Wünsche erfüllt.\n\nSeine minimalistische Form, die elegante helle Polsterung und die sorgfältig gearbeiteten Ziernähte verleihen Ihrem Wohnraum einen luxuriösen Charakter und fügen sich sowohl in moderne als auch in klassische Einrichtungen perfekt ein. Die verstellbaren Kopfstützen lassen sich individuell an Ihre Bedürfnisse anpassen und bieten beim Entspannen, beim Fernsehen oder bei Familientreffen eine angenehme Unterstützung.\n\nDie großzügigen Sitzflächen sorgen Tag für Tag für außergewöhnlichen Sitzkomfort, und die beeindruckende Liegefläche macht das Ecksofa zum Mittelpunkt Ihres Wohnzimmers – ideal zum Entspannen, für Gespräche und für gemeinsame Stunden.","kind":"text","title":"Beschreibung","admin_custom":true},{"body":"- Modernes, elegantes Design, das zu vielen Einrichtungen passt\n- 5 verstellbare Kopfstützen für mehr Komfort\n- Große Schlaffunktion – Delphin-Automatik für schnelles Ausklappen\n- Armlehne für noch mehr Komfort beim Sitzen\n- Großer Bettkasten\n- Bequeme Wellenfedern in den Sitzflächen\n- Stabile und langlebige Konstruktion\n- Hochelastischer Schaumstoff T30 im gesamten Möbelstück (Premium-Schaumstoff gegen +200 zł Aufpreis erhältlich)\n- Verchromte Füße 9 cm – erleichtern das Reinigen unter dem Möbelstück\n- Hohe Verarbeitungsqualität und Liebe zum Detail\n- Dekorative Steppnaht-Verzierung\n- Dekorative Einzüge in den Sitzflächen\n- Ideal für den täglichen Gebrauch und zum Entspannen!\n- Stoffe zur Auswahl! Wenn Sie sich für einen anderen Stoff oder eine andere Farbe interessieren und eigene Vorstellungen zur Anpassung dieses Modells haben, nehmen Sie gerne Kontakt mit uns auf! Wir helfen und beraten Sie gerne bei der Auswahl des perfekten Möbelstücks für Ihr Wohnzimmer!\n- Kostenlose Stoffmuster\n","kind":"text","title":"Produktspezifikation","admin_custom":true},{"body":"Monolith – Eleganz, die Sie jeden Tag begeistert\n\nWenn Sie sich ein Möbelstück wünschen, das luxuriös aussieht und sich zugleich im Alltag bewährt, ist der Stoff Monolith die perfekte Wahl. Seine samtige, außergewöhnlich weiche Oberfläche zieht mit einem dezenten Glanz die Blicke auf sich und verleiht Ihrem Wohnraum einen besonders eleganten Charakter.\n\nMonolith wurde für alle entwickelt, die sich nicht zwischen schönem Aussehen und Praktikabilität entscheiden möchten. Dank einer Technologie, die das Aufsaugen von Flüssigkeiten reduziert, ziehen versehentlich verschütteter Kaffee, Tee oder Saft nicht sofort in den Stoff ein, sodass sich der Fleck schnell entfernen lässt.\nDas ist der ideale Stoff für Familien mit Kindern, Tierbesitzer und alle, die von ihren Möbeln Langlebigkeit und ein makelloses Aussehen über viele Jahre erwarten.\n\nWarum entscheiden sich Kunden für Monolith?\n\n✔ Luxuriöses Aussehen, inspiriert von exklusiven Interieurs\n✔ Angenehme, samtige Oberfläche für außergewöhnlichen Komfort\n✔ Reduziertes Aufsaugen von Flüssigkeiten erleichtert die Reinigung\n✔ Hohe Beständigkeit gegen täglichen Gebrauch\n✔ Eleganter Effekt, der den Charakter jedes Wohnzimmers unterstreicht\n✔ Perfekte Verbindung aus Stil, Komfort und Funktionalität\n\nMonolith ist der Stoff für alle, die Premium-Qualität schätzen und möchten, dass ihre Möbel jeden Tag mit ihrem Aussehen begeistern.\n\n\nPoso – Weichheit, die ein gemütliches Zuhause schafft\n\nPoso ist einer der angesagtesten Stoffe der letzten Saisons. Seine charakteristische Struktur aus breitem Cord lässt Möbel überaus stilvoll wirken und verleiht dem Raum ein warmes, gemütliches Ambiente.\n\nSchon bei der ersten Berührung begeistert er mit seiner Weichheit und seinem Komfort. Dieser Stoff wurde für alle geschaffen, die es lieben, sich zu entspannen, Zeit mit der Familie zu verbringen und einen Raum zu gestalten, der zum Wohlfühlen einlädt. Ecksofas und Sofas im Stoff Poso werden zum natürlichen Mittelpunkt des häuslichen Lebens.\n\nDie Verbindung aus modernem Design und außergewöhnlichem Komfort lässt Poso sowohl in angesagte skandinavische und Loft-Einrichtungen als auch in moderne Arrangements perfekt einfügen.\nWarum lohnt sich die Wahl von Poso?\n\n✔ Angesagte Struktur aus breitem Cord, die alle Blicke auf sich zieht\n✔ Außergewöhnlich weiche und angenehme Oberfläche\n✔ Schafft eine warme und gemütliche Raumatmosphäre\n✔ Wirkt besonders schön auf großen Ecksofas und Sofas\n✔ Hohe Langlebigkeit und Beständigkeit gegen täglichen Gebrauch\n✔ Ideale Wahl für alle, die Komfort und modernen Stil schätzen\n\nPoso ist der Stoff, der Ihr Wohnzimmer zu einem Ort macht, den man gar nicht mehr verlassen möchte.","kind":"text","title":"Beschreibung des Stoffes","admin_custom":true},{"body":"Schaumstoff T30 – Komfort und Langlebigkeit serienmäßig\n\nIn der Standardausführung ist das Möbelstück mit hochwertigem Schaumstoff T30 ausgestattet, der eine optimale Verbindung aus Komfort, Elastizität und Langlebigkeit bietet. Dank der passenden Dichte schmiegt sich der Schaumstoff gut an den Körper an und sorgt sowohl beim täglichen Entspannen als auch bei längerem Gebrauch für Komfort.\n\nEs ist eine bewährte Lösung, die seit Jahren in Polstermöbeln zum Einsatz kommt und für eine stabile Unterstützung sowie Formbeständigkeit sorgt.\n\nDie Vorteile des Schaumstoffs T30:\n\n✔ Komfortable und bequeme Sitzfläche\n✔ Passende Elastizität beim Gebrauch\n✔ Gute Formbeständigkeit\n✔ Langlebigkeit und Widerstandsfähigkeit über Jahre\n✔ Ideale Wahl für den täglichen Gebrauch\nDer Schaumstoff T30 ist eine solide Grundlage für komfortable Entspannung, dank der das Möbelstück seine Eigenschaften über lange Zeit behält.\n\n\nSchaumstoff HR Premium – Komfort der Premium-Klasse\n\nFür die anspruchsvollsten Kunden bieten wir die Möglichkeit, das Möbelstück mit hochelastischem HR-Schaumstoff auszustatten. Dies ist eine Lösung, die in Möbeln der Premium-Klasse zum Einsatz kommt und den Komfort im täglichen Gebrauch deutlich erhöht.\n\nDer HR-Schaumstoff zeichnet sich durch außergewöhnliche Elastizität und die Fähigkeit aus, schnell in seine ursprüngliche Form zurückzukehren. Dadurch passt sich die Sitzfläche besser an die Körperform an und vermittelt ein Gefühl von Weichheit bei gleichzeitig angemessener Unterstützung.\n\nZusätzlich überzeugt der HR-Schaumstoff durch erhöhte Langlebigkeit und eine bessere Luftzirkulation, was den Komfort über viele Jahre hinweg steigert.\n\nWarum lohnt sich die Wahl des HR-Schaumstoffs?\n\n✔ Höherer Sitz- und Entspannungskomfort\n✔ Bessere Anpassung an die Körperform\n✔ Mehr Elastizität und Federung der Sitzfläche\n✔ Schnelle Rückkehr in die ursprüngliche Form\n✔ Erhöhte Langlebigkeit und Beständigkeit im Gebrauch\n✔ Komfort der Premium-Klasse an jedem Tag\n\nWenn Ihnen maximaler Komfort und höchste Qualität wichtig sind, ist der HR-Schaumstoff eine hervorragende Investition in den Komfort Ihres Möbelstücks über viele Jahre.\n","kind":"text","title":"Weitere Informationen","admin_custom":true},{"body":"Informationen für unsere Kunden! • Die Farbe des Möbelstücks kann je nach Monitoreinstellungen und Beleuchtung leicht abweichen. WIR EMPFEHLEN, UNSERE KOSTENLOSEN STOFFMUSTER ZU NUTZEN – DIE MUSTER KÖNNEN PER PRIVATER NACHRICHT ODER TELEFONISCH BESTELLT WERDEN\n• Bitte geben Sie den Namen des gewählten Stoffes bei der Bestellung an,\n• Das Ecksofa ist in einer rechtsseitigen oder linksseitigen Version erhältlich – bitte geben Sie die gewünschte Variante in der Nachricht zur Bestellung an (die Seite des Ecksofas bestimmen Sie, indem Sie davor stehen)\n\n!! Wenn Sie sich für ein Ecksofa von uns entscheiden, setzen Sie auf Qualität, Komfort und bewährte Lösungen direkt vom polnischen Hersteller.\n- Wir bieten eine große Auswahl an Stoffen – verschiedene Arten, mit denen Sie das Möbelstück mühelos an Ihren Stil und Ihre Bedürfnisse anpassen.\n- Wir achten auf jedes Detail, damit unsere Ecksofas über Jahre Freude bereiten und mit ihrem Aussehen begeistern. Mit Ihrem Kauf bei uns unterstützen Sie polnische Unternehmen und heimische Produktion – eine Entscheidung, die wirklich zählt.","kind":"text","title":"Informationen für unsere Kunden","admin_custom":true},{"kind":"image","image_alt":"","image_url":"https://tlvgsddpiikolgdwuwmc.supabase.co/storage/v1/object/public/products/1782134641828-99afb993-6a55-49fd-9d7e-189e2af82542.jpg"}]$secs$::jsonb,
  needs_translation = false
where id = '57266819-9145-405f-8c62-2bd5a125c6b4';

-- 64b18769-9219-492c-b09f-0edf8fcb146b
update public.products set
  name_de = $n$Schlafsofa RIVEN 3-Sitzer ausziehbar mit Schlaffunktion und beweglichen Kopfstützen$n$,
  color_de = $c$Rosa$c$,
  material_de = $m$Trinity$m$,
  description_sections_de = $secs$[{"kind":"image","caption":"Ein Sofa, das jeden Tag mit Design und Komfort begeistert","image_alt":"Wunderschönes Sofa mit tiefen Nähten!","image_url":"https://tlvgsddpiikolgdwuwmc.supabase.co/storage/v1/object/public/products/1782161099569-09dd4fa1-7a04-4d91-a67a-91763556e9fa.jpg"},{"body":"Ein Sofa, das jeden Tag mit Design und Komfort begeistert\n\nVerleihen Sie Ihrem Zuhause eine Prise Eleganz und besondere Gemütlichkeit. Das Sofa RIVEN zieht alle Blicke auf sich – mit seinem zarten, puderrosa Farbton und den eindrucksvollen vertikalen Nähten, die ihm einen modernen und luxuriösen Charakter verleihen. Die sorgfältig gearbeiteten Steppungen betonen die schlanke Silhouette des Möbelstücks und machen es zu einem echten Schmuckstück im Wohnzimmer.\n\nDie weichen, federnden Rückenkissen sorgen für eine hervorragende Unterstützung des Rückens, während die komfortable Sitzfläche nach einem langen Tag zum Entspannen einlädt. Jeder Moment auf diesem Sofa verbindet Bequemlichkeit, Erholung und Genuss. Der angenehm weiche Bezug umhüllt Sie mit Komfort und schafft den idealen Ort zum Ausruhen, für gesellige Stunden mit den Liebsten oder für Abende mit dem Lieblingsbuch.\nEin Möbelstück, das für alle geschaffen wurde, die sowohl außergewöhnliches Design als auch alltäglichen Komfort schätzen. Dank seiner zeitlosen Form und der durchdachten Details fügt sich das Sofa perfekt in moderne wie auch klassischere Einrichtungen ein.\n","kind":"text","title":"Produktbeschreibung","admin_custom":true},{"body":"Produkteigenschaften:\n\n- außergewöhnlich weiche und bequeme Kissen mit Silikonkugel-Füllung!\n- elegante, dekorative Nähte an Rückenlehne, Seiten und Sitzfläche,\n- modische Farbgebung, die dem Raum Leichtigkeit und Charakter verleiht,\n- solide Verarbeitung und Liebe zum Detail,\n- die ideale Verbindung von Stil, Komfort und Funktionalität.\n- hohe Holzfüße 10 cm,\n- großer Bettkasten für Bettwäsche,\n- Wellenfedern Typ B in den Sitzflächen,\n- DL-Mechanik als Ausklapphilfe,\n- T30-Schaum im gesamten Möbel,\n- große Auswahl an Bezugsstoffen – wenn Sie sich eine andere Struktur wünschen, kontaktieren Sie uns gerne!\n\n\nEinmal Platz genommen, möchten Sie nicht mehr aufstehen – dieses Sofa wurde geschaffen, um mit seinem Aussehen zu begeistern und Sie jeden Tag mit Komfort zu verwöhnen.","kind":"text","title":"Produktspezifikation","admin_custom":true},{"body":"Stoff Trinity – Weichheit und Eleganz für jeden Tag!\n\nTrinity ist ein außergewöhnlich angenehmer Velours-Stoff, der mit seiner Weichheit und seinem dezenten Aussehen begeistert. Die zarte, samtige Oberfläche verleiht den Möbeln einen eleganten Charakter und sorgt zugleich für hohen Komfort. Das Material präsentiert sich in jedem Interieur wunderschön – von modernen Arrangements bis hin zu klassischeren Räumen.\n\nDank seiner hohen Abriebfestigkeit eignet sich der Stoff Trinity hervorragend für den täglichen Gebrauch und behält über lange Zeit sein attraktives Aussehen. Eine ideale Wahl für alle, die eine Verbindung von Ästhetik, Komfort und Langlebigkeit suchen.\n\n**Mit Trinity erhalten Sie einen Stoff, der durch seine Weichheit begeistert, die Eleganz des Möbels unterstreicht und jeden Moment der Entspannung noch angenehmer macht.**\n\n**Stoff Monolith – Luxus, Langlebigkeit und außergewöhnlicher Stil**\n\nMonolith ist ein hochwertiger Samtstoff, der für sein edles Aussehen und seine hervorragenden Gebrauchseigenschaften geschätzt wird. Seine samtige Struktur reflektiert das Licht auf sanfte Weise und verleiht den Möbeln einen exklusiven Charakter und eine intensive Farbtiefe. Ein Material, das vom ersten Blick an die Aufmerksamkeit auf sich zieht und das Prestige jedes Interieurs unterstreicht.\n\nDer Stoff ist mit einer speziellen Beschichtung ausgestattet, die das Aufsaugen von Flüssigkeiten reduziert – verschüttete Getränke bleiben so auf der Oberfläche und lassen sich leicht entfernen. Die hohe Abriebfestigkeit und Widerstandsfähigkeit gegenüber dem täglichen Gebrauch sorgen dafür, dass Monolith über Jahre sein makelloses Aussehen bewahrt.\n\nMonolith ist die ideale Wahl für alle, die von ihren Möbeln nicht nur ein schönes Design erwarten, sondern auch Praktikabilität, Langlebigkeit und Komfort auf höchstem Niveau.\n","kind":"text","title":"Stoffbeschreibung","admin_custom":true},{"body":"T30-Schaum – Komfort und Langlebigkeit serienmäßig. In der Standardversion ist das Möbelstück mit hochwertigem T30-Schaum ausgestattet, der eine optimale Verbindung von Komfort, Elastizität und Langlebigkeit bietet. Dank seiner geeigneten Dichte passt sich der Schaum dem Körper gut an und garantiert Komfort sowohl bei der täglichen Entspannung als auch bei längerer Nutzung. Eine bewährte Lösung, die seit Jahren in Polstermöbeln eingesetzt wird und für stabile Unterstützung sowie Formbeständigkeit sorgt. Vorteile des T30-Schaums: ✔ Komfortable und bequeme Sitzfläche ✔ Angemessene Elastizität bei der Nutzung ✔ Gute Formbeständigkeit ✔ Langlebigkeit und Strapazierfähigkeit über Jahre ✔ Ideale Wahl für den täglichen Gebrauch. Der T30-Schaum ist eine solide Grundlage für komfortable Erholung, dank der das Möbelstück seine Eigenschaften über lange Zeit bewahrt. HR-Schaum Premium – Komfort der Premiumklasse. Für die anspruchsvollsten Kunden bieten wir die Möglichkeit, das Möbelstück mit hochelastischem HR-Schaum auszustatten. Dies ist eine Lösung, die in Möbeln der Premiumklasse eingesetzt wird und den Komfort im täglichen Gebrauch erheblich steigert. Der HR-Schaum zeichnet sich durch außergewöhnliche Elastizität und die Fähigkeit aus, schnell in seine ursprüngliche Form zurückzukehren. Dadurch passt sich die Sitzfläche besser an die Körperform an und vermittelt ein Gefühl von Weichheit bei gleichzeitig angemessener Unterstützung. Zudem zeichnet sich der HR-Schaum durch erhöhte Langlebigkeit und eine bessere Luftzirkulation aus, was den Nutzungskomfort über viele Jahre hinweg beeinflusst. Warum lohnt sich der HR-Schaum? ✔ Höherer Sitz- und Erholungskomfort ✔ Bessere Anpassung an die Körperform ✔ Größere Elastizität und Federung der Sitzfläche ✔ Schnelle Rückkehr in die ursprüngliche Form ✔ Erhöhte Langlebigkeit und Nutzungsbeständigkeit ✔ Komfort der Premiumklasse an jedem Tag. Wenn Ihnen maximaler Komfort und höchste Qualität am Herzen liegen, ist der HR-Schaum eine ausgezeichnete Investition in den Nutzungskomfort Ihres Möbels über lange Jahre.","kind":"text","title":"Weitere Informationen","admin_custom":true},{"body":"Informationen für den Kunden! • Die Farbe des Möbels kann je nach Monitoreinstellungen und Beleuchtung leicht abweichen. WIR EMPFEHLEN, UNSERE KOSTENLOSEN STOFFPROBEN ZU NUTZEN – PROBEN KÖNNEN PER PRIVATNACHRICHT ODER TELEFONISCH BESTELLT WERDEN. • Bitte geben Sie den Namen des gewählten Stoffes bei der Bestellung an. • Das Eck-Sofa ist in rechts- oder linksseitiger Ausführung erhältlich – bitte geben Sie die gewünschte Variante in der Nachricht zur Bestellung an (die Seite des Eck-Sofas bestimmen wir, indem wir davor stehen). !! Wenn Sie sich für ein Eck-Sofa bei uns entscheiden, setzen Sie auf Qualität, Komfort und bewährte Lösungen direkt vom polnischen Hersteller. - Wir bieten eine große Auswahl an Bezugsstoffen – verschiedene Arten, mit denen Sie das Möbel mühelos an Ihren Stil und Ihre Bedürfnisse anpassen können. - Wir achten auf jedes Detail, damit unsere Eck-Sofas über Jahre Freude bereiten und mit ihrem Aussehen begeistern. Mit einem Kauf bei uns unterstützen Sie polnische Unternehmen und die heimische Produktion – eine Entscheidung, die wirklich von Bedeutung ist.","kind":"text","title":"Informationen für den Kunden","admin_custom":true},{"kind":"image","image_alt":"","image_url":"https://tlvgsddpiikolgdwuwmc.supabase.co/storage/v1/object/public/products/1782162031747-8229dc65-bbc3-4cf4-9011-e1374926a9d5.jpg"}]$secs$::jsonb,
  needs_translation = false
where id = '64b18769-9219-492c-b09f-0edf8fcb146b';


